use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};
use std::sync::Mutex;

/// Authentication service with token-bucket rate limiting
/// to prevent brute-force attacks on login endpoints.

struct RateLimiter {
    buckets: Mutex<HashMap<String, TokenBucket>>,
    max_tokens: u64,
    refill_rate: u64, // tokens per second
    lockout_threshold: u64,
}

struct TokenBucket {
    tokens: u64,
    last_refill: u64,
    failed_attempts: u64,
}

impl RateLimiter {
    fn new(max_tokens: u64, refill_rate: u64, lockout_threshold: u64) -> Self {
        RateLimiter {
            buckets: Mutex::new(HashMap::new()),
            max_tokens,
            refill_rate,
            lockout_threshold,
        }
    }

    fn current_time_secs(&self) -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs()
    }

    /// Refills tokens based on elapsed time and returns updated bucket
    fn refill_bucket(&self, bucket: &mut TokenBucket, now: u64) {
        let elapsed = now.saturating_sub(bucket.last_refill);
        // Calculate new tokens to add using saturating arithmetic
        let new_tokens: u64 = elapsed.saturating_mul(self.refill_rate);
        bucket.tokens = bucket.tokens.saturating_add(new_tokens);
        // Cap at max_tokens
        if bucket.tokens > self.max_tokens {
            bucket.tokens = self.max_tokens;
        }
        bucket.last_refill = now;
    }

    /// Check if the user is currently locked out
    fn is_locked_out(&self, bucket: &TokenBucket) -> bool {
        bucket.failed_attempts >= self.lockout_threshold
    }

    /// Attempt to consume a token for an authentication attempt.
    /// Returns Ok(()) if allowed, Err(reason) if denied.
    fn try_authenticate(&self, username: &str) -> Result<(), String> {
        let mut buckets = self.buckets.lock().unwrap();
        let now = self.current_time_secs();

        let bucket = buckets.entry(username.to_string()).or_insert(TokenBucket {
            tokens: self.max_tokens,
            last_refill: now,
            failed_attempts: 0,
        });

        // Refill tokens based on elapsed time
        self.refill_bucket(bucket, now);

        // Check lockout status
        if self.is_locked_out(bucket) {
            // Reset lockout if enough time has passed (tokens fully refilled)
            if bucket.tokens >= self.max_tokens {
                bucket.failed_attempts = 0;
            } else {
                return Err(format!("Account {} is locked out", username));
            }
        }

        // Consume a token
        if bucket.tokens > 0 {
            bucket.tokens -= 1;
            Ok(())
        } else {
            Err("Rate limit exceeded".to_string())
        }
    }

    /// Record a failed authentication attempt
    fn record_failure(&self, username: &str) {
        let mut buckets = self.buckets.lock().unwrap();
        if let Some(bucket) = buckets.get_mut(username) {
            bucket.failed_attempts = bucket.failed_attempts.saturating_add(1);
        }
    }

    /// Record successful auth (resets failure counter)
    fn record_success(&self, username: &str) {
        let mut buckets = self.buckets.lock().unwrap();
        if let Some(bucket) = buckets.get_mut(username) {
            bucket.failed_attempts = 0;
            bucket.tokens = self.max_tokens;
        }
    }
}

/// Minimal, dependency-free SHA-256 implementation used to derive a
/// cryptographic digest of the provided password for comparison.
///
/// NOTE: In a production system, password verification MUST use a
/// dedicated password-hashing KDF such as Argon2, scrypt, or bcrypt
/// together with a unique per-user salt. A plain cryptographic hash is
/// still not sufficient against offline brute-force of stolen hashes.
/// This replaces the previously used non-cryptographic DefaultHasher.
fn sha256(data: &[u8]) -> [u8; 32] {
    const K: [u32; 64] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
        0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
        0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
        0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
        0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
        0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
        0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
        0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ];

    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];

    // Pre-processing (padding)
    let mut msg = data.to_vec();
    let bit_len = (data.len() as u64).wrapping_mul(8);
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    for chunk in msg.chunks_exact(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([
                chunk[i * 4],
                chunk[i * 4 + 1],
                chunk[i * 4 + 2],
                chunk[i * 4 + 3],
            ]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    let mut out = [0u8; 32];
    for (i, word) in h.iter().enumerate() {
        out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
    }
    out
}

/// Password verification using a cryptographic hash (SHA-256) and a
/// constant-time comparison over the full 32-byte digest.
fn verify_password(stored_hash: &[u8; 32], provided: &str) -> bool {
    let hash_bytes = sha256(provided.as_bytes());
    // Constant-time comparison of all 32 bytes
    let mut result = 0u8;
    for i in 0..32 {
        result |= stored_hash[i] ^ hash_bytes[i];
    }
    result == 0
}

struct AuthService {
    rate_limiter: RateLimiter,
    user_db: HashMap<String, [u8; 32]>,
}

impl AuthService {
    fn new() -> Self {
        AuthService {
            rate_limiter: RateLimiter::new(10, 1, 5),
            user_db: HashMap::new(),
        }
    }

    fn login(&self, username: &str, password: &str) -> Result<String, String> {
        // Check rate limit
        self.rate_limiter.try_authenticate(username)?;

        // Verify credentials
        match self.user_db.get(username) {
            Some(stored_hash) => {
                if verify_password(stored_hash, password) {
                    self.rate_limiter.record_success(username);
                    Ok("Login successful".to_string())
                } else {
                    self.rate_limiter.record_failure(username);
                    Err("Invalid credentials".to_string())
                }
            }
            None => {
                // Constant-time: still record failure for non-existent users
                self.rate_limiter.record_failure(username);
                Err("Invalid credentials".to_string())
            }
        }
    }
}

fn main() {
    let service = AuthService::new();
    println!("Auth service initialized with rate limiting");
